#pragma once

#include <cstddef>
#include <functional>
#include <memory>
#include <string>
#include <vector>

#include "bar.hpp"
#include "nnfx_strategy.hpp"
#include "system_run.hpp"
#include "param_space.hpp"

// Every baseline found in include/baselines/ (the list is generated by CMake). Nothing here needs editing
// when a baseline is added.

// A baseline with its type hidden, so tests and tools can drive any of them the same way.
class AnyLine
{
public:
    virtual ~AnyLine() = default;
    virtual void update(const Bar& bar) = 0;
    virtual bool ready() const = 0;
    virtual double value() const = 0;
    virtual std::unique_ptr<AnyLine> clone() const = 0;
};

struct BaselineInfo
{
    std::string name;                                                        // the file name, e.g. "kijun"
    std::vector<ParamRange> ranges;                                          // the legal values: --params must stay inside them
    std::function<std::size_t(const Params&)> warmupBars;
    std::function<std::unique_ptr<AnyLine>(const Params&)> makeLine;
    std::function<StrategyFactory(const NnfxOptions&)> nnfx;                 // NnfxStrategy
};

// Sorted by name.
const std::vector<BaselineInfo>& baselineRegistry();

// nullptr if there is no such baseline.
const BaselineInfo* findBaseline(const std::string& name);

// "ema, kijun, sma"
std::string baselineNames();
